// Entrega a mensagem do broadcast pelo Telegram (Bot API oficial). Contatos
// que ainda não vincularam o chat (não abriram o bot e compartilharam o
// número) saem direto como falha, com o motivo registrado (RF-06).
const body = $('Webhook').first().json.body;
const base = $env.TELEGRAM_API_URL || 'https://api.telegram.org';
const token = $env.TELEGRAM_BOT_TOKEN;
const callbackUrl = (body.callbackUrl || '')
  .replace('127.0.0.1', 'host.docker.internal')
  .replace('localhost', 'host.docker.internal');

const results = [];
for (const c of body.contacts || []) {
  let status = 'falha';
  let detail;
  if (!token) {
    detail = 'TELEGRAM_BOT_TOKEN não configurado no N8N.';
  } else if (!c.telegramChatId) {
    detail = 'Contato ainda não vinculou o Telegram (abrir o bot e compartilhar o número).';
  } else {
    try {
      const res = await this.helpers.httpRequest({
        method: 'POST',
        url: `${base}/bot${token}/sendMessage`,
        body: { chat_id: c.telegramChatId, text: body.message },
        json: true,
      });
      status = res.ok ? 'enviado' : 'falha';
      detail = res.ok ? `Entregue no Telegram (mensagem ${res.result.message_id}).` : res.description;
    } catch (err) {
      detail = `Telegram recusou o envio: ${err.description || err.message}`;
    }
  }
  results.push({ json: { logId: c.logId, status, detail, callbackUrl } });
}
return results;
